- name: Install separate pinned current and historical TypeScript profiles
  id: typescript
  shell: bash
  run: |
    npm install --prefix "$RUNNER_TEMP/psc0-typescript-7.0.2" --ignore-scripts --save-exact --no-audit --no-fund typescript@7.0.2
    npm install --prefix "$RUNNER_TEMP/psc0-typescript-5.8.3" --ignore-scripts --save-exact --no-audit --no-fund typescript@5.8.3
    node --input-type=module <<'NODE'
    import assert from 'node:assert/strict';
    import { appendFileSync, copyFileSync, mkdirSync, readFileSync, realpathSync } from 'node:fs';
    import path from 'node:path';
    import { createRequire } from 'node:module';
    import { spawnSync } from 'node:child_process';
    const require = createRequire(import.meta.url);
    const directory = path.resolve('dist/typescript-profile/install');
    mkdirSync(directory, { recursive: true });
    for (const [profile, version] of [['current', '7.0.2'], ['historical', '5.8.3']]) {
      const prefix = path.join(process.env.RUNNER_TEMP, 'psc0-typescript-' + version);
      const manifestPath = require.resolve('typescript/package.json', { paths: [prefix] });
      const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
      assert.equal(manifest.name, 'typescript');
      assert.equal(manifest.version, version);
      const bin = typeof manifest.bin === 'string' ? manifest.bin : manifest.bin?.tsc;
      assert.equal(typeof bin, 'string', 'PSC0_TYPESCRIPT_BIN_METADATA');
      const launcher = realpathSync(path.resolve(path.dirname(manifestPath), bin));
      const result = spawnSync(process.execPath, [launcher, '--version'], { encoding: 'utf8' });
      assert.equal(result.status, 0, result.stderr);
      assert.equal(result.stdout.trim(), 'Version ' + version);
      appendFileSync(process.env.GITHUB_OUTPUT, profile + '-cli=' + launcher + '\n');
      copyFileSync(path.join(prefix, 'package-lock.json'), path.join(directory, profile + '-package-lock.json'));
      copyFileSync(manifestPath, path.join(directory, profile + '-package.json'));
      if (profile === 'current') {
        appendFileSync(process.env.GITHUB_ENV, 'PSC0_TSC=' + launcher + '\nPSC0_TYPESCRIPT_VERSION=' + version + '\n');
      } else {
        appendFileSync(process.env.GITHUB_OUTPUT, 'historical-path=' + path.join(prefix, 'node_modules/.bin') + path.delimiter + process.env.PATH + '\n');
      }
    }
    NODE

